css:
.bk-otomo3 h2{font-size:1.18em; color:#fff; background:#1d5e3b; padding:1.3mm 2.5mm; margin:0 0 2.5mm; border-radius:3px;}
.bk-otomo3 h3{font-size:1em; color:#1d5e3b; border-left:4px solid #1d5e3b; padding-left:2mm; margin:4mm 0 1.5mm;}
.bk-otomo3 p{margin:0 0 2mm;}
.bk-otomo3 table{border-collapse:collapse; width:100%; font-size:0.818em; margin:1mm 0 1mm;}
.bk-otomo3 th,.bk-otomo3 td{border:1px solid #b6d3c2; padding:0.9mm 1.3mm; vertical-align:top;}
.bk-otomo3 th{background:#e1efe6; font-weight:bold;}
.bk-otomo3 td.r{text-align:right; white-space:nowrap;}
.bk-otomo3 td.c{text-align:center; white-space:nowrap;}
.bk-otomo3 .src{font-size:0.682em; color:#777; margin:0 0 2.5mm;}
.bk-otomo3 .note{background:#fff6dd; border:1px solid #e8cf86; border-radius:3px; padding:1.8mm 2.5mm; margin:2mm 0; font-size:0.818em;}
.bk-otomo3 .note b{color:#a35a00;}
.bk-otomo3 .new{color:#c00000; font-weight:bold;}
